    // 计算一个长度为L的连续段中，减少x个字符的最小代价
    static long[] calcRunCost(int L, long[] a) {
        // f[i][j]：前i个字符，恰好减少j个字符的最小代价
        long[][] f = new long[L + 1][L];
        for (int i = 0; i <= L; i++) {
