                // 从当前位置开始压缩长度为k的一段
                for (int k = 2; k <= L - i; k++) {
                    int nj = j + k - 1;
                    long cost = f[i][j] + a[k];
                    if (f[i + k][nj] > cost) {
                        f[i + k][nj] = cost;
                    }
                }
            }
        }

        long[] res = new long[L];
        for (int j = 0; j < L; j++) {
            res[j] = f[L][j];
        }
        return res;
    }

    // 求解单组测试
    static long solveCase(int n, int m, String s, long[] a) {
        int need = n - m;

        // 拆分连续段
        int[] runs = new int[n];
        int runCount = 0;
        int cnt = 1;
        for (int i = 1; i < n; i++) {
            if (s.charAt(i) == s.charAt(i - 1)) {
                cnt++;
            } else {
                runs[runCount++] = cnt;
                cnt = 1;
            }
        }
        runs[runCount++] = cnt;

        // 分组背包
        long[] dp = new long[need + 1];
        for (int i = 0; i <= need; i++) {
            dp[i] = INF;
        }
        dp[0] = 0;

        for (int idx = 0; idx < runCount; idx++) {
            int L = runs[idx];
            long[] costRun = calcRunCost(L, a);
