                cost = f[i][j] + w[k]
                if f[i + k][nj] > cost:
                    f[i + k][nj] = cost

    res = [INF] * L
    for j in range(L):
        res[j] = f[L][j]
    return res


def solve_case(n, m, s, arr):
    need = n - m
    if need < 0:
        return -1

    # 代价数组 w[k] 表示融合长度为k的段所需代价，k从1开始
    w = [0] * (n + 1)
    for i in range(1, n + 1):
        w[i] = arr[i - 1]

