        else:
            runs.append(cnt)
            cnt = 1
    runs.append(cnt)

    # 分组背包
    dp = [INF] * (need + 1)
    dp[0] = 0

    for L in runs:
        cost_run = calc_run_cost(L, w)
        ndp = [INF] * (need + 1)

        for old in range(need + 1):
            if dp[old] == INF:
                continue
            max_dec = min(L - 1, need - old)
            for dec in range(max_dec + 1):
                if cost_run[dec] == INF:
                    continue
                val = dp[old] + cost_run[dec]
                if ndp[old + dec] > val:
                    ndp[old + dec] = val

        dp = ndp

    return -1 if dp[need] == INF else dp[need]


