public class Main {
    static final long INF = (long) 4e18;

    // 计算一个长度为L的同色连续段中，减少x个字符的最小代价
    static long[] calcRunCost(int L, long[] w) {
        long[][] f = new long[L + 1][L];
        for (int i = 0; i <= L; i++) {
            for (int j = 0; j < L; j++) {
                f[i][j] = INF;
            }
        }
        f[0][0] = 0;

        for (int i = 0; i < L; i++) {
            for (int j = 0; j < L; j++) {
                if (f[i][j] == INF) {
                    continue;
                }

                // 不融合第i+1块瓷砖
                if (f[i + 1][j] > f[i][j]) {
                    f[i + 1][j] = f[i][j];
                }

                // 从第i+1块开始融合长度为k的一段
                for (int k = 2; k <= L - i; k++) {
                    int nj = j + k - 1;
                    long cost = f[i][j] + w[k];
                    if (f[i + k][nj] > cost) {
                        f[i + k][nj] = cost;
                    }
                }
            }
        }

        long[] res = new long[L];
        for (int j = 0; j < L; j++) {
            res[j] = f[L][j];
        }
        return res;
    }

    static long solveCase(int n, int m, String s, long[] w) {
        int need = n - m;
        if (need < 0) return -1;

        // 拆分成极长同色连续段
        int[] runs = new int[n];
        int runCnt = 0;
        int cnt = 1;
        for (int i = 1; i < n; i++) {
            if (s.charAt(i) == s.charAt(i - 1)) {
                cnt++;
            } else {
                runs[runCnt++] = cnt;
                cnt = 1;
            }
        }
        runs[runCnt++] = cnt;

        // 分组背包
        long[] dp = new long[need + 1];
        for (int i = 0; i <= need; i++) {
            dp[i] = INF;
        }
        dp[0] = 0;

        for (int idx = 0; idx < runCnt; idx++) {
            int L = runs[idx];
            long[] costRun = calcRunCost(L, w);
            long[] ndp = new long[need + 1];
            for (int i = 0; i <= need; i++) {
                ndp[i] = INF;
            }

            for (int old = 0; old <= need; old++) {
                if (dp[old] == INF) continue;
                int maxDec = Math.min(L - 1, need - old);
                for (int dec = 0; dec <= maxDec; dec++) {
                    if (costRun[dec] == INF) continue;
                    long val = dp[old] + costRun[dec];
                    if (ndp[old + dec] > val) {
                        ndp[old + dec] = val;
                    }
                }
            }
            dp = ndp;
        }

        return dp[need] == INF ? -1 : dp[need];
    }

